with gaps as (select *, case when event_time - lag(event_time) over (partition by session_id order by event_time, id) > interval '90' day then 1 else 0 end as is_new_session from web_events), sessions_web_events as (select *, sum(is_new_session) over (partition by session_id order by event_time, id rows between unbounded preceding and current row) as island_id from gaps) select date_trunc('week', event_time) as week_start, event_type, page, count(case when event_type = 'click' then 1 end) as click_count, count(*) filter (where page = '/product') as product_rows, count(case when event_type = 'page_view' then 1 end) as page_view_count, count(*) filter (where page = '/search') as search_rows from sessions_web_events group by grouping sets ((date_trunc('week', event_time), event_type, page), (date_trunc('week', event_time), event_type), (date_trunc('week', event_time)), ());
